package com.company.platform.commerce.infrastructure.persistence;
import com.company.platform.commerce.domain.cart.*; import com.company.platform.commerce.domain.pricing.Money; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository; import java.sql.Timestamp; import java.util.*;
@Repository public class JdbcCartItemRepository implements CartItemRepository { private final JdbcTemplate jdbc; public JdbcCartItemRepository(JdbcTemplate jdbc){this.jdbc=jdbc;} public CartItem save(UUID t,CartItem i){jdbc.update("INSERT INTO cart_items(id,cart_id,tenant_id,sellable_product_id,quantity,unit_price,currency,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET quantity=?,unit_price=?,currency=?,updated_at=?",i.id(),i.cartId(),t,i.sellableProductId(),i.quantity(),i.unitPrice().amount(),i.unitPrice().currency().getCurrencyCode(),Timestamp.from(i.createdAt()),Timestamp.from(i.updatedAt()),i.quantity(),i.unitPrice().amount(),i.unitPrice().currency().getCurrencyCode(),Timestamp.from(i.updatedAt()));return i;} private CartItem map(java.sql.ResultSet r,int n)throws java.sql.SQLException{return new CartItem((UUID)r.getObject("id"),(UUID)r.getObject("cart_id"),(UUID)r.getObject("sellable_product_id"),r.getInt("quantity"),new Money(r.getBigDecimal("unit_price"),Currency.getInstance(r.getString("currency"))),r.getTimestamp("created_at").toInstant(),r.getTimestamp("updated_at").toInstant());} public List<CartItem> findAllByTenantIdAndCartId(UUID t,UUID c){return jdbc.query("SELECT * FROM cart_items WHERE tenant_id=? AND cart_id=? ORDER BY created_at",this::map,t,c);} public Optional<CartItem> findByTenantIdAndCartIdAndId(UUID t,UUID c,UUID id){return jdbc.query("SELECT * FROM cart_items WHERE tenant_id=? AND cart_id=? AND id=?",this::map,t,c,id).stream().findFirst();} public void deleteByTenantIdAndCartIdAndId(UUID t,UUID c,UUID id){jdbc.update("DELETE FROM cart_items WHERE tenant_id=? AND cart_id=? AND id=?",t,c,id);}}
